test('T001 ordinary completion close bridge: a first accepted V2 attempt reaches its exact terminal receipt', () => {
  withAutonomousWorkspace(noRegistryPlanBytes(SPEC_PATH), (root) => {
    // Arrange
    const taskStateFile = Buffer.from(`${JSON.stringify({
      [TASKS_PATH]: {
        glyphs: { [TASK_KEY]: '~' },
        updated_at: '2025-12-31T00:00:00.000Z',
      },
    }, null, 2)}\n`);
    fs.mkdirSync(path.join(root, '.dude/state'), { recursive: true });
    fs.writeFileSync(path.join(root, '.dude/state/task-state.json'), taskStateFile);
    const initialState = autonomousState();
    const emptyInput = () => cliInput(t002RetentionInput(root, [], [], []));
    const inspected = t003Invoke('inspect', {
      trigger: 'explicit-inspection',
      input: emptyInput(),
    });
    const authorized = t003Invoke('authorize', {
      trigger: 'start',
      state: initialState,
      input: emptyInput(),
      assessment: {
        ...transitionAssessment('execute-task', { targets: ['src/t001-ordinary.mjs'] }),
        evidenceHash: inspected.inspection.evidenceHash,
      },
      mode: 'ordinary',
    });
    const fixture = t002PendingFixture({
      target: TARGET,
      attemptOrdinal: 1,
      action: 'execute-task',
      mode: 'ordinary',
      evidenceHash: inspected.inspection.evidenceHash,
      materialInputs: {
        targets: ['src/t001-ordinary.mjs'],
        operations: ['execute-task'],
        checks: ['verification'],
      },
      checkOutcome: 'passed',
      verdict: 'accepted',
    });
    const attemptIdentity = fixture.attemptIdentity;
    const envelopes = fixture;
    /** @param {Record<string, unknown>[]} currentEvents @param {Record<string, unknown>[]} laneEvents */
    const retained = (currentEvents, laneEvents = currentEvents) => cliInput(
      t002RetentionInput(root, currentEvents, laneEvents, [fixture]),
    );
    const completion = {
      version: 2,
      target: TARGET,
      attemptIdentity,
      route: 'lightweight-task',
      outcome: 'succeeded',
      operations: ['execute-task'],
      changedTargets: ['src/t001-ordinary.mjs'],
      resultIdentity: envelopes.verification.resultIdentity,
      verificationEnvelopeIdentity: envelopes.verification.envelopeIdentity,
      reviewEnvelopeIdentity: envelopes.review.envelopeIdentity,
      findingIdentities: [],
    };
    const mutation = {
      version: 1,
      lane: 'lightweight',
      kind: 'task-completed',
      reason: 'task-completed',
      target: canonicalTarget(TARGET),
      fromGlyph: '~',
      toGlyph: 'x',
      blocker: { kind: 'unchanged', before: null, after: null },
      eventLines: { kind: 'none' },
      ownerLog: { kind: 'none' },
      snapshotUpdatedAt: T005_TIME,
    };

    // Act
    const captured = t003Invoke('complete', {
      mode: 'capture',
      state: authorized.authorization.state,
      input: retained([], []),
      completion,
    });
    const occurrenceEvents = captured.completion.projectionBatch.events;
    const verified = t003Invoke('transition', {
      mode: 'verify-projection',
      state: captured.completion.state,
      input: retained(occurrenceEvents),
      projectionBatch: captured.completion.projectionBatch,
    });
    const finalized = t003Invoke('complete', {
      mode: 'finalize',
      state: captured.completion.state,
      input: retained(occurrenceEvents),
      projectionBatch: captured.completion.projectionBatch,
    });
    const binding = t005LightweightBinding(root, TARGET, IDEA_PATH, '~', null, taskStateFile);
    const issued = t003Invoke('transition', {
      mode: 'issue-lane-permit',
      state: finalized.completion.state,
      input: retained(occurrenceEvents),
      mutation,
      lanePrestate: binding.lanePrestate,
      targetMapping: binding.targetMapping,
    });
    const permit = issued.transition.permit;
    const ownerCapture = recoveryRuntime.capturedBytesV1(binding.ideaFile);
    const laneResult = applyLightweightWorkRequest({
      version: 1,
      operation: 'work-set',
      root: fs.realpathSync(root),
      owner: {
        ideaPath: IDEA_PATH,
        specPath: SPEC_PATH,
        ownerCapture,
        ownerBindingHash: binding.targetMapping.ownerBindingHash,
      },
      target: clone(TARGET),
      state: finalized.completion.state,
      permit,
      mapping: binding.targetMapping,
      expected: {
        tasksPath: TASKS_PATH,
        tasks: recoveryRuntime.capturedBytesV1(binding.tasksFile),
        taskStatePath: '.dude/state/task-state.json',
        taskState: recoveryRuntime.capturedBytesV1(taskStateFile),
      },
      mutation,
    });
    assert.equal(laneResult.ok, true, JSON.stringify(laneResult));
    const receipt = laneResult.receipt;
    const poststateTasks = fs.readFileSync(path.join(root, TASKS_PATH));
    const poststateInput = cliInput(t002RetentionInputWithTaskHistory(
      root,
      occurrenceEvents,
      poststateTasks,
      [fixture],
    ));
    const committed = t003Invoke('transition', {
      mode: 'commit-lane-receipt',
      state: finalized.completion.state,
      input: poststateInput,
      permit,
      receipt,
    });

    // Assert
    assert.equal(authorized.authorization.authorized, true);
    assert.equal(canonicalJson(authorized.authorization.state), canonicalJson(fixture.state));
    assert.equal(verified.transition.verified, true);
    assert.equal(finalized.completion.finalized, true);
    assert.equal(finalized.completion.completed, true);
    assert.equal(Object.hasOwn(finalized.completion.state, 'learningGovernance'), false);
    assert.equal(issued.transition.issued, true);
    assert.equal(permit.governanceIdentity, null);
    assert.equal(permit.governancePhase, null);
    assert.equal(permit.attemptIdentity, attemptIdentity);
    assert.equal(permit.subjectRunStateHash, sha256(canonicalJson(finalized.completion.state)));
    assert.equal(permit.mutationIdentity, sha256(canonicalJson(mutation)));
    assert.equal(permit.targetMappingHash, binding.targetMappingHash);
    assert.equal(permit.lanePrestateHash, binding.lanePrestateHash);
    assert.match(fs.readFileSync(path.join(root, TASKS_PATH), 'utf8'), new RegExp(`- \\[x\\] ${TASK_KEY}`));
    assert.equal(receipt.tasksPoststateHash, sha256(fs.readFileSync(path.join(root, TASKS_PATH))));
    assert.equal(receipt.taskStatePoststateHash, sha256(fs.readFileSync(path.join(root, '.dude/state/task-state.json'))));
    assert.equal(receipt.ownerPoststateHash, sha256(fs.readFileSync(path.join(root, IDEA_PATH))));
    assert.equal(committed.transition.committed, true);
    assert.equal(committed.transition.reason, 'lane-receipt-committed');
    assert.equal(committed.transition.terminalEvidenceIdentity, receipt.receiptHash);
    assert.equal(canonicalJson(committed.transition.state), canonicalJson(finalized.completion.state));
    validateRunState(committed.transition.state);
  });
});

/** @param {string} root @param {Record<string, unknown>} [overrides] */
function t001OrdinaryCompletionFixture(root, overrides = {}) {
  const attemptOrdinal = overrides.attemptOrdinal || 1;
  const materialInputs = clone(overrides.materialInputs || {
    targets: [`src/t001-ordinary-${attemptOrdinal}.mjs`],
    operations: ['execute-task'],
    checks: ['verification'],
  });
  const fixture = t002PendingFixture({
    attemptOrdinal,
    action: 'execute-task',
    mode: 'ordinary',
    materialInputs,
    priorCompleted: clone(overrides.priorCompleted || []),
    checkOutcome: overrides.checkOutcome || 'passed',
    verdict: overrides.verdict || 'accepted',
    ...(overrides.evidenceHash ? { evidenceHash: overrides.evidenceHash } : {}),
  });
  /** @param {Record<string, unknown>[]} currentEvents @param {Record<string, unknown>[]} laneEvents @param {ReturnType<typeof t002PendingFixture>[]} trustedFixtures */
  const input = (currentEvents, laneEvents = currentEvents, trustedFixtures = [fixture]) => cliInput(
    t002RetentionInput(root, currentEvents, laneEvents, trustedFixtures),
  );
  const captured = t003Invoke('complete', {
    mode: 'capture',
    state: fixture.state,
    input: input([], []),
    completion: fixture.completion,
  });
  const events = captured.completion.projectionBatch.events;
  const verified = t003Invoke('transition', {
    mode: 'verify-projection',
    state: captured.completion.state,
    input: input(events),
    projectionBatch: captured.completion.projectionBatch,
  });
  const finalized = t003Invoke('complete', {
    mode: 'finalize',
    state: captured.completion.state,
    input: input(events),
    projectionBatch: captured.completion.projectionBatch,
  });
  const binding = t005LightweightBinding(root, TARGET, IDEA_PATH, '~', null, overrides.taskStateFile);
  const mutation = {
    version: 1,
    lane: 'lightweight',
    kind: 'task-completed',
    reason: 'task-completed',
    target: canonicalTarget(TARGET),
    fromGlyph: '~',
    toGlyph: 'x',
    blocker: { kind: 'unchanged', before: null, after: null },
    eventLines: { kind: 'none' },
    ownerLog: { kind: 'none' },
    snapshotUpdatedAt: T005_TIME,
  };
  return { fixture, captured, events, verified, finalized, binding, mutation, input };
}

test('T001 ordinary completion close bridge KEEP guard: active and unsettled retained evaluation sequences refuse task close', () => {
  withAutonomousWorkspace(noRegistryPlanBytes(SPEC_PATH), (root) => {
    // Arrange
    const terminal = t001OrdinaryCompletionFixture(root);
    const activeIdentities = {
      activeCheckpointIdentity: sha256('retained-close-checkpoint'),
      activeCandidateIdentity: sha256('retained-close-candidate'),
    };
    const rows = [
      ['active', evaluationSequenceRow('close-active', activeIdentities)],
      ['unsettled', evaluationSequenceRow('close-unsettled', { state: 'unsettled', ...activeIdentities })],
    ];

    for (const [label, sequence] of rows) {
      const state = {
        ...clone(terminal.finalized.completion.state),
        evaluationSequences: [sequence],
      };
      validateRunState(state);
      const before = canonicalJson(state);

      // Act
      const issued = t003Invoke('transition', {
        mode: 'issue-lane-permit',
        state,
        input: terminal.input(terminal.events),
        mutation: terminal.mutation,
        lanePrestate: terminal.binding.lanePrestate,
        targetMapping: terminal.binding.targetMapping,
      });

      // Assert
      assert.equal(issued.transition.issued, false, label);
      assert.equal(issued.transition.reason, 'governance-unresolved', label);
      assert.equal(Object.hasOwn(issued.transition, 'permit'), false, label);
      assert.equal(canonicalJson(issued.transition.state), before, label);
    }
  });
});

test('T001 ordinary completion close bridge: issuance refuses every incomplete, stale, conflicting, or ambiguous authority', () => {
  withAutonomousWorkspace(noRegistryPlanBytes(SPEC_PATH), (root) => {
    // Arrange
    const terminal = t001OrdinaryCompletionFixture(root);
    const finalState = terminal.finalized.completion.state;
    const alternate = t001OrdinaryCompletionFixture(root, {
      evidenceHash: t005Hash('ordinary-alternate-evidence'),
      materialInputs: {
        targets: ['src/t001-ordinary-alternate.mjs'],
        operations: ['execute-task'],
        checks: ['verification'],
      },
    });
    const failed = t001OrdinaryCompletionFixture(root, { checkOutcome: 'failed' });
    const rejected = t001OrdinaryCompletionFixture(root, { verdict: 'rejected' });
    const second = t001OrdinaryCompletionFixture(root, {
      attemptOrdinal: 2,
      priorCompleted: finalState.completed,
      materialInputs: {
        targets: ['src/t001-ordinary-second.mjs'],
        operations: ['execute-task'],
        checks: ['verification'],
      },
    });
    const secondState = second.finalized.completion.state;
    const firstTuple = clone(finalState.completed[0]);
    const secondTuple = clone(secondState.completed[1]);
    const missingVerification = t002RetentionInput(
      root,
      terminal.events,
      terminal.events,
      [terminal.fixture],
    );
    missingVerification.verification = [];
    const missingReview = t002RetentionInput(
      root,
      terminal.events,
      terminal.events,
      [terminal.fixture],
    );
    missingReview.review = [];
    const staleTrusted = t001OrdinaryCompletionFixture(root, {
      evidenceHash: t005Hash('ordinary-stale-trusted-evidence'),
      materialInputs: {
        targets: ['src/t001-ordinary-stale-trusted.mjs'],
        operations: ['execute-task'],
        checks: ['verification'],
      },
    });
    const governed = {
      ...clone(finalState),
      learningGovernance: t002RequiredGovernance([
        t002ApproachEvent({ attemptOrdinal: 1, basisLabel: 'ordinary-active-governance' }),
        t002ApproachEvent({ attemptOrdinal: 2, basisLabel: 'ordinary-active-governance' }),
      ]),
    };
    const projectionFlow = t003PublicFlow(root, 'finding', 'selected-alternative');
    const projected = projectionFlow.learned.learning.state;
    const projectedInput = cliInput(t002RetentionInput(
      root,
      projectionFlow.governedEvents,
      projectionFlow.governedEvents,
      projectionFlow.fixtures,
    ));
    const evaluation = {
      ...clone(finalState),
      evaluationSequences: [evaluationSequenceRow('ordinary-close-guard')],
    };
    const forgedTuple = clone(finalState);
    forgedTuple.completed[0].resultHash = t005Hash('ordinary-forged-completed-result');
    const missingTuple = { ...clone(finalState), completed: [] };
    const duplicatedTuple = {
      ...clone(secondState),
      completed: [clone(secondTuple), clone(secondTuple)],
    };
    const nonFinalTuple = clone(secondState);
    assert.deepEqual(nonFinalTuple.completed[0], firstTuple);
    const duplicateEvents = [...terminal.events, ...terminal.events];
    const ambiguousEvents = [...terminal.events, ...alternate.events];
    const wrongTargetMutation = {
      ...clone(terminal.mutation),
      target: canonicalTarget({ ...TARGET, taskKey: SECOND_TASK_KEY }),
    };
    const cases = [
      {
        label: 'pending attempt',
        state: terminal.fixture.state,
        input: terminal.input([], []),
      },
      {
        label: 'pending completion',
        state: terminal.captured.completion.state,
        input: terminal.input(terminal.events),
      },
      {
        label: 'active governance obligation',
        state: governed,
        input: terminal.input(terminal.events),
      },
      {
        label: 'active projection obligation',
        state: projected,
        input: projectedInput,
      },
      {
        label: 'active evaluation obligation',
        state: evaluation,
        input: terminal.input(terminal.events),
      },
      {
        label: 'wrong target',
        state: finalState,
        input: terminal.input(terminal.events),
        mutation: wrongTargetMutation,
      },
      {
        label: 'missing trusted verification capture',
        state: finalState,
        input: cliInput(missingVerification),
      },
      {
        label: 'missing trusted review capture',
        state: finalState,
        input: cliInput(missingReview),
      },
      {
        label: 'stale trusted captures',
        state: finalState,
        input: terminal.input(terminal.events, terminal.events, [staleTrusted.fixture]),
      },
      {
        label: 'current-run-only retention',
        state: finalState,
        input: terminal.input(terminal.events, []),
      },
      {
        label: 'lane-only retention',
        state: finalState,
        input: terminal.input([], terminal.events),
      },
      {
        label: 'duplicate retained occurrence',
        state: finalState,
        input: terminal.input(duplicateEvents, duplicateEvents),
      },
      {
        label: 'conflicting retained occurrence',
        state: finalState,
        input: terminal.input(
          terminal.events,
          alternate.events,
          [terminal.fixture, alternate.fixture],
        ),
      },
      {
        label: 'verification-failed disposition',
        state: failed.finalized.completion.state,
        input: failed.input(failed.events),
      },
      {
        label: 'review-rejected disposition',
        state: rejected.finalized.completion.state,
        input: rejected.input(rejected.events),
      },
      {
        label: 'forged completed tuple',
        state: forgedTuple,
        input: terminal.input(terminal.events),
      },
      {
        label: 'duplicated final completed tuple',
        state: duplicatedTuple,
        input: second.input(second.events),
      },
      {
        label: 'accepted tuple is not final',
        state: nonFinalTuple,
        input: terminal.input(terminal.events),
      },
      {
        label: 'multiple accepted occurrences at final ordinal',
        state: finalState,
        input: terminal.input(
          ambiguousEvents,
          ambiguousEvents,
          [terminal.fixture, alternate.fixture],
        ),
      },
    ];

    // Act and Assert
    for (const row of cases) {
      validateRunState(row.state);
      const stateBytes = canonicalJson(row.state);
      const result = t003Invoke('transition', {
        mode: 'issue-lane-permit',
        state: row.state,
        input: row.input,
        mutation: row.mutation || terminal.mutation,
        lanePrestate: terminal.binding.lanePrestate,
        targetMapping: terminal.binding.targetMapping,
      });
      assert.equal(result.transition.issued, false, row.label);
      assert.equal(Object.hasOwn(result.transition, 'permit'), false, row.label);
      assert.equal(canonicalJson(result.transition.state), stateBytes, row.label);
    }

    // A missing tuple cannot pass RunState validation: overallUsed must equal
    // pending plus completed attempts. Exercise the nearest public boundary and
    // prove request validation grants no permit or mutation authority.
    const missingRequest = {
      mode: 'issue-lane-permit',
      state: missingTuple,
      input: terminal.input(terminal.events),
      mutation: terminal.mutation,
      lanePrestate: terminal.binding.lanePrestate,
      targetMapping: terminal.binding.targetMapping,
    };
    const missingBytes = canonicalJson(missingRequest);
    assert.throws(
      () => validateRunState(missingTuple),
      /overallUsed must equal pending plus completed attempts/,
    );
    const missingResult = runRecoveryCli('transition', missingRequest);
    assert.notEqual(missingResult.status, 0);
    assert.equal(JSON.parse(missingResult.stderr).error.code, 'recovery-invalid-request');
    assert.equal(missingResult.stdout, '');
    assert.equal(canonicalJson(missingRequest), missingBytes);
  });
});

test('T001 ordinary completion close bridge: commit refuses stale, transferred, forged, mismatched, or replayed authority', () => {
  withAutonomousWorkspace(noRegistryPlanBytes(SPEC_PATH), (root) => {
    // Arrange
    fs.mkdirSync(path.join(root, '.dude/state'), { recursive: true });
    fs.writeFileSync(path.join(root, '.dude/state/task-state.json'), T005_TASK_STATE);
    const terminal = t001OrdinaryCompletionFixture(root);
    const state = terminal.finalized.completion.state;
    const issued = t003Invoke('transition', {
      mode: 'issue-lane-permit',
      state,
      input: terminal.input(terminal.events),
      mutation: terminal.mutation,
      lanePrestate: terminal.binding.lanePrestate,
      targetMapping: terminal.binding.targetMapping,
    });
    const permit = issued.transition.permit;
    const receipt = t005AtomicReceipt(permit, terminal.binding, true);
    const unchangedPoststateReceipt = t005Receipt({
      version: 1,
      lane: 'lightweight',
      permitHash: permit.permitHash,
      mutationIdentity: permit.mutationIdentity,
      target: clone(permit.target),
      targetMappingHash: terminal.binding.targetMappingHash,
      lanePrestateHash: terminal.binding.lanePrestateHash,
      tasksPoststateHash: sha256(fs.readFileSync(path.join(root, TASKS_PATH))),
      taskStatePoststateHash: sha256(fs.readFileSync(path.join(root, '.dude/state/task-state.json'))),
      ownerPoststateHash: sha256(fs.readFileSync(path.join(root, IDEA_PATH))),
      targetStateChanged: true,
    });
    const changedState = clone(state);
    changedState.policy.overall = 2;
    const wrongTargetInput = () => {
      const input = terminal.input(terminal.events);
      input.target = canonicalTarget({ ...TARGET, taskKey: SECOND_TASK_KEY });
      return input;
    };
    const forgedAttemptBody = {
      ...permit,
      attemptIdentity: t005Hash('ordinary-forged-permit-attempt'),
    };
    delete forgedAttemptBody.permitHash;
    const forgedAttempt = t005Permit(forgedAttemptBody);
    const { receiptHash: _receiptHash, ...receiptBody } = receipt;
    const mismatchedPermitReceipt = t005Receipt({
      ...receiptBody,
      permitHash: t005Hash('ordinary-foreign-permit'),
    });
    const mismatchedMappingReceipt = t005Receipt({
      ...receiptBody,
      targetMappingHash: t005Hash('ordinary-foreign-mapping'),
    });
    const mismatchedMutationReceipt = t005Receipt({
      ...receiptBody,
      mutationIdentity: t005Hash('ordinary-foreign-mutation'),
    });
    const replayInput = () => {
      const prefix = [
        transitionTasksBytes([{ id: TASK_KEY, glyph: 'x' }]).toString('utf8').trimEnd(),
        '',
        '## Lightweight Execution History',
        '',
      ].join('\n');
      const taskHistory = Buffer.concat([
        Buffer.from(prefix),
        ...terminal.events.map((event) => Buffer.from(`${t002V2EventLine(event)}\n`)),
      ]);
      return cliInput(t002RetentionInputWithTaskHistory(
        root,
        terminal.events,
        taskHistory,
        [terminal.fixture],
      ));
    };
    const cases = [
      {
        label: 'changed RunState makes permit stale',
        state: changedState,
        input: () => terminal.input(terminal.events),
        permit,
        receipt,
        reason: 'permit-stale',
      },
      {
        label: 'changed retained evidence after issuance',
        state,
        input: () => terminal.input(terminal.events, []),
        permit,
        receipt,
        reason: 'governance-unresolved',
      },
      {
        label: 'wrong target Inspection',
        state,
        input: wrongTargetInput,
        permit,
        receipt,
        reason: 'permit-target-mismatch',
      },
      {
        label: 'forged attempt identity in self-consistent permit',
        state,
        input: () => terminal.input(terminal.events),
        permit: forgedAttempt,
        receipt: t005AtomicReceipt(forgedAttempt, terminal.binding, true),
        reason: 'governance-unresolved',
      },
      {
        label: 'mismatched receipt permit',
        state,
        input: () => terminal.input(terminal.events),
        permit,
        receipt: mismatchedPermitReceipt,
        reason: 'lane-receipt-mismatch',
      },
      {
        label: 'mismatched receipt mapping',
        state,
        input: () => terminal.input(terminal.events),
        permit,
        receipt: mismatchedMappingReceipt,
        reason: 'lane-receipt-mismatch',
      },
      {
        label: 'mismatched receipt mutation',
        state,
        input: () => terminal.input(terminal.events),
        permit,
        receipt: mismatchedMutationReceipt,
        reason: 'lane-receipt-mismatch',
      },
      {
        label: 'lane prestate changed after issuance',
        state,
        input: replayInput,
        permit,
        receipt,
        reason: 'lane-receipt-mismatch',
      },
      {
        label: 'unchanged lane poststate forged as changed',
        state,
        input: () => terminal.input(terminal.events),
        permit,
        receipt: unchangedPoststateReceipt,
        reason: 'lane-receipt-mismatch',
      },
    ];

    // Act and Assert
    assert.equal(issued.transition.issued, true);
    assert.match(fs.readFileSync(path.join(root, TASKS_PATH), 'utf8'), new RegExp(`- \\[~\\] ${TASK_KEY}`));
    recoveryRuntime.validateLightweightAtomicReceiptV1(unchangedPoststateReceipt);
    for (const row of cases) {
      validateRunState(row.state);
      const stateBytes = canonicalJson(row.state);
      const result = t003Invoke('transition', {
        mode: 'commit-lane-receipt',
        state: row.state,
        input: row.input(),
        permit: row.permit,
        receipt: row.receipt,
      });
      assert.equal(result.transition.committed, false, row.label);
      assert.equal(result.transition.reason, row.reason, row.label);
      assert.equal(Object.hasOwn(result.transition, 'terminalEvidenceIdentity'), false, row.label);
      assert.equal(canonicalJson(result.transition.state), stateBytes, row.label);
    }
  });
});

test('T005 acyclic permits: a verified no-progress exit issues and commits its exact lane mutation', () => {
  withAutonomousWorkspace(noRegistryPlanBytes(SPEC_PATH), (root) => {
    // Arrange
    const flow = t003PublicFlow(root, 'approach', 'no-progress');
    const verifiedState = flow.branchTransition.transition.state;
    const input = () => t004Input(root, flow, flow.learnedEvents);
    const binding = t005LightweightBinding(root, TARGET, IDEA_PATH, '~', null);
    const noProgressMutation = {
      version: 1,
      lane: 'lightweight',
      kind: 'task-blocked',
      reason: 'no-progress',
      target: canonicalTarget(TARGET),
      fromGlyph: '~',
      toGlyph: '!',
      blocker: { kind: 'add', before: null, after: 'no-progress: every credible alternative repeats a failed approach' },
      eventLines: { kind: 'none' },
      ownerLog: { kind: 'none' },
      snapshotUpdatedAt: T005_TIME,
    };
    const endedState = t003Invoke('transition', {
      mode: 'controlled-end',
      state: verifiedState,
      input: input(),
    }).transition.state;

    // Act
    const issued = t003Invoke('transition', {
      mode: 'issue-lane-permit',
      state: verifiedState,
      input: input(),
      mutation: noProgressMutation,
      lanePrestate: binding.lanePrestate,
      targetMapping: binding.targetMapping,
    });
    const permit = issued.transition.permit;
    const committed = t003Invoke('transition', {
      mode: 'commit-lane-receipt',
      state: verifiedState,
      input: input(),
      permit,
      receipt: t005AtomicReceipt(permit, binding, true),
    });
    const afterControlledEnd = t003Invoke('transition', {
      mode: 'issue-lane-permit',
      state: endedState,
      input: input(),
      mutation: noProgressMutation,
      lanePrestate: binding.lanePrestate,
      targetMapping: binding.targetMapping,
    });

    // Assert
    assert.equal(verifiedState.learningGovernance.phase, 'no-progress-verified');
    assert.equal(issued.transition.issued, true);
    assert.equal(permit.governancePhase, 'no-progress-verified');
    assert.equal(permit.attemptIdentity, null);
    // The no-progress exit blocks the exact task, so unlike a controlled end its
    // receipt asserts the changed target state and still commits.
    assert.equal(committed.transition.committed, true);
    assert.equal(committed.transition.reason, 'lane-receipt-committed');
    assert.equal(committed.transition.receipt.targetStateChanged, true);
    assert.equal(Object.hasOwn(committed.transition.state, 'learningGovernance'), false);
    validateRunState(committed.transition.state);
    // A controlled end owns the same phase and authorizes no fresh block.
    assert.equal(afterControlledEnd.transition.issued, false);
    assert.equal(afterControlledEnd.transition.reason, 'learning-phase-mismatch');
  });
});

test('T005 acyclic permits: an alternative-verified record with unbacked identities issues no terminal permit', () => {
  withAutonomousWorkspace(noRegistryPlanBytes(SPEC_PATH), (root) => {
    // Arrange
    const terminal = t005VerifiedTerminal(root);
    /** @param {string} field @param {string} value */
    const drift = (field, value) => {
      const state = clone(terminal.verifiedState);
      state.learningGovernance[field] = value;
      // A self-consistent RunState: nothing in the record itself objects.
      validateRunState(state);
      return state;
    };
    const unbackedAlternative = drift('selectedAlternativeIdentity', t005Hash('unbacked-alternative'));
    const unbackedCheck = drift('discriminatingCheckIdentity', t005Hash('unbacked-check'));
    const unbackedAttempt = drift('authorizedAttemptIdentity', t005Hash('unbacked-attempt'));
    /** @param {Record<string, unknown>} state */
    const issue = (state) => t003Invoke('transition', {
      mode: 'issue-lane-permit',
      state,
      input: terminal.retained(terminal.attemptEvents),
      mutation: terminal.terminalMutation,
      lanePrestate: terminal.binding.lanePrestate,
      targetMapping: terminal.binding.targetMapping,
    });

    // Act
    const backed = issue(terminal.verifiedState);
    const alternative = issue(unbackedAlternative);
    const check = issue(unbackedCheck);
    const attempt = issue(unbackedAttempt);

    // Assert
    assert.equal(backed.transition.issued, true);
    assert.equal(backed.transition.permit.governancePhase, 'alternative-verified');
    // The retained learning review names the alternative and its discriminating
    // check; the stored record never asserts either on its own.
    assert.equal(alternative.transition.reason, 'alternative-selection-mismatch');
    assert.equal(check.transition.reason, 'alternative-selection-mismatch');
    // Completion authority is an executed attempt retained as an accepted occurrence.
    assert.equal(attempt.transition.reason, 'occurrence-retention-incomplete');
    for (const [refused, before] of [
      [alternative, unbackedAlternative],
      [check, unbackedCheck],
      [attempt, unbackedAttempt],
    ]) {
      assert.deepEqual(refused.inspection.blockers, []);
      assert.equal(refused.transition.issued, false);
      assert.equal(Object.hasOwn(refused.transition, 'permit'), false);
      assert.equal(canonicalJson(refused.transition.state), canonicalJson(before));
    }
  });
});

test('T005 acyclic permits: a hand-built terminal permit releases nothing from a non-exit governance phase', () => {
  withAutonomousWorkspace(noRegistryPlanBytes(SPEC_PATH), (root) => {
    // Arrange
    const terminal = t005VerifiedTerminal(root);
    const flow = terminal.flow;
    // Every governed phase the acyclic order passes through before the two
    // verified exits. A caller holds each state, so it copies the governance
    // identity and phase straight out of the state it already has.
    const nonExit = [
      ['reviewed', flow.learned.learning.state],
      ['projected', flow.learningVerified.transition.state],
      ['alternative-inspected', flow.branchTransition.transition.state],
      ['alternative-authorized', terminal.authorizedState],
    ];
    /** @param {Record<string, unknown>} state */
    const handBuilt = (state) => t005Permit({
      version: 1,
      kind: 'lane-mutation',
      origin: 'dude-work',
      lane: 'lightweight',
      operation: 'work-set',
      target: canonicalTarget(TARGET),
      subjectRunStateHash: sha256(canonicalJson(state)),
      governanceIdentity: state.learningGovernance.governanceIdentity,
      governancePhase: state.learningGovernance.phase,
      attemptIdentity: terminal.attemptIdentity,
      targetMappingHash: terminal.binding.targetMappingHash,
      lanePrestateHash: terminal.binding.lanePrestateHash,
      mutationIdentity: sha256(canonicalJson(terminal.terminalMutation)),
    });

    // Act
    const refused = nonExit.map(([phase, state]) => {
      const permit = handBuilt(state);
      return { phase, state, permit, result: t003Invoke('transition', {
        mode: 'commit-lane-receipt',
        state,
        input: terminal.retained(terminal.attemptEvents),
        permit,
        receipt: t005AtomicReceipt(permit, terminal.binding, true),
      }) };
    });

    // Assert
    for (const row of refused) {
      assert.equal(row.state.learningGovernance.phase, row.phase, row.phase);
      recoveryRuntime.validateLaneMutationPermitV1(row.permit);
      assert.deepEqual(row.result.inspection.blockers, [], row.phase);
      // The lifecycle exits only from `alternative-verified` and
      // `no-progress-verified`, so no mid-cycle phase releases the obligation.
      assert.equal(row.result.transition.committed, false, row.phase);
      assert.equal(row.result.transition.reason, 'learning-phase-mismatch', row.phase);
      assert.equal(Object.hasOwn(row.result.transition, 'receipt'), false, row.phase);
      assert.equal(Object.hasOwn(row.result.transition, 'terminalEvidenceIdentity'), false, row.phase);
      assert.equal(canonicalJson(row.result.transition.state), canonicalJson(row.state), row.phase);
      assert.equal(Object.hasOwn(row.result.transition.state, 'learningGovernance'), true, row.phase);
    }
    // The exact same hand-built shape still commits from the verified exit.
    const exitPermit = handBuilt(terminal.verifiedState);
    const exit = t003Invoke('transition', {
      mode: 'commit-lane-receipt',
      state: terminal.verifiedState,
      input: terminal.retained(terminal.attemptEvents),
      permit: exitPermit,
      receipt: t005AtomicReceipt(exitPermit, terminal.binding, true),
    });
    assert.equal(terminal.verifiedState.learningGovernance.phase, 'alternative-verified');
    assert.equal(exit.transition.committed, true);
    assert.equal(exit.transition.reason, 'lane-receipt-committed');
    assert.equal(Object.hasOwn(exit.transition.state, 'learningGovernance'), false);
  });
});

test('T005 acyclic permits: an alternative-verified record with unbacked identities commits no terminal receipt', () => {
  withAutonomousWorkspace(noRegistryPlanBytes(SPEC_PATH), (root) => {
    // Arrange
    const terminal = t005VerifiedTerminal(root);
    /** @param {string} field @param {string} value */
    const drift = (field, value) => {
      const state = clone(terminal.verifiedState);
      state.learningGovernance[field] = value;
      // A self-consistent RunState: nothing in the record itself objects.
      validateRunState(state);
      return state;
    };
    const unbackedAlternative = drift('selectedAlternativeIdentity', t005Hash('commit-unbacked-alternative'));
    const unbackedCheck = drift('discriminatingCheckIdentity', t005Hash('commit-unbacked-check'));
    const unbackedAttempt = drift('authorizedAttemptIdentity', t005Hash('commit-unbacked-attempt'));
    /** @param {Record<string, unknown>} state */
    const commit = (state) => {
      const permit = t005Permit({
        version: 1,
        kind: 'lane-mutation',
        origin: 'dude-work',
        lane: 'lightweight',
        operation: 'work-set',
        target: canonicalTarget(TARGET),
        subjectRunStateHash: sha256(canonicalJson(state)),
        governanceIdentity: state.learningGovernance.governanceIdentity,
        governancePhase: state.learningGovernance.phase,
        attemptIdentity: state.learningGovernance.authorizedAttemptIdentity,
        targetMappingHash: terminal.binding.targetMappingHash,
        lanePrestateHash: terminal.binding.lanePrestateHash,
        mutationIdentity: sha256(canonicalJson(terminal.terminalMutation)),
      });
      return t003Invoke('transition', {
        mode: 'commit-lane-receipt',
        state,
        input: terminal.retained(terminal.attemptEvents),
        permit,
        receipt: t005AtomicReceipt(permit, terminal.binding, true),
      });
    };
    /** @param {Record<string, unknown>} state */
    const issue = (state) => t003Invoke('transition', {
      mode: 'issue-lane-permit',
      state,
      input: terminal.retained(terminal.attemptEvents),
      mutation: terminal.terminalMutation,
      lanePrestate: terminal.binding.lanePrestate,
      targetMapping: terminal.binding.targetMapping,
    });

    // Act
    const backed = commit(terminal.verifiedState);
    const alternative = commit(unbackedAlternative);
    const check = commit(unbackedCheck);
    const attempt = commit(unbackedAttempt);

    // Assert
    // The exact same permit shape commits against the backed record.
    assert.equal(backed.transition.committed, true);
    assert.equal(backed.transition.reason, 'lane-receipt-committed');
    assert.equal(Object.hasOwn(backed.transition.state, 'learningGovernance'), false);
    // A permit is a plain digest, so the commit rebinds the retained review and
    // the retained accepted occurrence exactly as issuance does.
    assert.equal(alternative.transition.reason, 'alternative-selection-mismatch');
    assert.equal(check.transition.reason, 'alternative-selection-mismatch');
    assert.equal(attempt.transition.reason, 'occurrence-retention-incomplete');
    for (const [refused, before] of [
      [alternative, unbackedAlternative],
      [check, unbackedCheck],
      [attempt, unbackedAttempt],
    ]) {
      assert.deepEqual(refused.inspection.blockers, []);
      assert.equal(refused.transition.committed, false);
      assert.equal(Object.hasOwn(refused.transition, 'receipt'), false);
      assert.equal(Object.hasOwn(refused.transition, 'terminalEvidenceIdentity'), false);
      assert.equal(canonicalJson(refused.transition.state), canonicalJson(before));
      assert.equal(Object.hasOwn(refused.transition.state, 'learningGovernance'), true);
    }
    // Issuance and the releasing commit refuse the same drift for the same reason.
    for (const [refused, state] of [
      [alternative, unbackedAlternative],
      [check, unbackedCheck],
      [attempt, unbackedAttempt],
    ]) {
      assert.equal(issue(state).transition.reason, refused.transition.reason);
    }
  });
});

test('T005 incident contracts: a Feature 007 owner idea under another path refuses in the closed set', () => {
  withIncidentWorkspace((root) => {
    // Arrange: the exact same defined owner package, resolved by `spec_path:`
    // from a differently named idea file.
    const request = t005AcceptedEvidence(root);
    const renamedIdeaPath = '.dude/ideas/renamed-technical-docs-pack-remediation.md';
    fs.renameSync(path.join(root, F7_IDEA_PATH), path.join(root, renamedIdeaPath));
    const input = () => cliInput(t005IncidentInput(root, [], []));

    // Act
    const inspected = t003Invoke('inspect', { trigger: 'explicit-inspection', input: input() });
    const corrected = t003Invoke('transition', {
      mode: 'incident-correction',
      state: autonomousState(),
      input: input(),
      incident: {
        ...request,
        captures: {
          ...request.captures,
          tasks: recoveryRuntime.capturedBytesV1(fs.readFileSync(path.join(root, F7_TASKS_PATH))),
        },
      },
    });

    // Assert
    const owner = inspected.inspection.items.find((item) => item.source === 'owner-log');
    assert.equal(owner.status, 'present');
    assert.equal(JSON.parse(owner.text).ideaPath, renamedIdeaPath);
    assert.deepEqual(inspected.inspection.blockers, []);
    // A freshly resolved owner the incident contracts cannot name is a closed
    // refusal, not a throw.
    assert.equal(corrected.transition.prepared, false);
    assert.equal(corrected.transition.reason, 'incident-correction-not-authorized');
    assert.equal(Object.hasOwn(corrected.transition, 'preview'), false);
    assert.deepEqual(corrected.transition.state, autonomousState());
  });
});

test('T005 incident contracts: an exact-evidence preview binds its lines, owner line, snapshot, and rollback', () => {
  withIncidentWorkspace((root) => {
    // Arrange
    const evidence = t005IncidentEvidence(root);
    const request = t005AcceptedEvidence(root);
    const preview = t003Invoke('transition', {
      mode: 'incident-correction',
      state: autonomousState(),
      input: cliInput(t005IncidentInput(root, evidence.events, evidence.fixtures)),
      incident: {
        ...request,
        captures: {
          ...request.captures,
          tasks: recoveryRuntime.capturedBytesV1(fs.readFileSync(path.join(root, F7_TASKS_PATH))),
        },
      },
    }).transition.preview;
    /** @param {(body: Record<string, unknown>) => void} mutate */
    const reidentify = (mutate) => {
      const body = clone(preview);
      delete body.previewIdentity;
      mutate(body);
      return { ...body, previewIdentity: sha256(canonicalJson(body)) };
    };

    // Act: every mutation stays self-consistent, so only the derived bindings
    // can refuse it.
    const droppedGovernanceLine = reidentify((body) => {
      body.mutationCore.eventLines.lines.splice(2, 1);
    });
    const reorderedFindingLines = reidentify((body) => {
      const lines = body.mutationCore.eventLines.lines;
      [lines[0], lines[1]] = [lines[1], lines[0]];
    });
    const foreignReviewEnvelopes = reidentify((body) => {
      body.evidence.reviewEnvelopeIdentities = [t005Hash('foreign-review-a'), t005Hash('foreign-review-b')];
    });
    const driftedOwnerLine = reidentify((body) => {
      body.mutationCore.ownerLog.exactLines = ['- an unrelated coordinator note'];
    });
    const driftedOwnerRevision = reidentify((body) => {
      body.mutationCore.ownerLog.expectedOwnerHash = t005Hash('other-owner-revision');
    });
    const driftedSnapshot = reidentify((body) => {
      body.mutationCore.snapshotUpdatedAt = '2026-02-02T00:00:00Z';
    });
    const foreignRollbackBytes = reidentify((body) => {
      const captures = body.rollback.captures;
      captures[1] = {
        path: captures[1].path,
        bytes: recoveryRuntime.capturedBytesV1(Buffer.from('a different tasks revision\n')),
      };
      const rollbackBody = { version: body.rollback.version, captures };
      body.rollback = { ...rollbackBody, rollbackIdentity: sha256(canonicalJson(rollbackBody)) };
    });

    // Assert
    recoveryRuntime.validateIncidentCorrectionPreviewV1(preview);
    assert.equal(preview.mutationCore.eventLines.lines.length, 4);
    for (const [mutated, pattern] of [
      [droppedGovernanceLine, /must append the exact ordered finding pair, Governance Event, and Incident Supersession Event/],
      [reorderedFindingLines, /must append the exact ordered finding pair, Governance Event, and Incident Supersession Event/],
      [foreignReviewEnvelopes, /must be the exact retained review envelopes of those occurrences/],
      [driftedOwnerLine, /must be the exact intent-bound owner line/],
      [driftedOwnerRevision, /must be the exact prestate owner revision/],
      [driftedSnapshot, /must equal the intent operation time/],
      [foreignRollbackBytes, /must capture the exact prestate revision it restores/],
    ]) {
      assert.equal(
        /** @type {Record<string, unknown>} */ (mutated).previewIdentity,
        sha256(canonicalJson(Object.fromEntries(
          Object.entries(/** @type {Record<string, unknown>} */ (mutated)).filter(([key]) => key !== 'previewIdentity'),
        ))),
      );
      assert.throws(
        () => recoveryRuntime.validateIncidentCorrectionPreviewV1(mutated),
        /** @type {RegExp} */ (pattern),
      );
    }
  });
});



// --- Feature 010 T001: shared lane-history event-type declaration ---------

/** One complete declared audit-only lane-history event. @param {Record<string, unknown>} [overrides] */
function t001AuditOnlyEvent(overrides = {}) {
  const body = {
    type: 'incident-supersession',
    version: 1,
    incidentIdentity: t002Hash('t001-incident'),
    intentIdentity: t002Hash('t001-intent'),
    target: canonicalTarget(F7_TARGET),
    priorDispositionIdentity: t002Hash('t001-prior-disposition'),
    acceptedFeatureEvidenceIdentity: t002Hash('t001-accepted-feature-evidence'),
    branch: 'exact-evidence',
    conclusion: 'unauthorized-block-superseded',
    resultingTargetState: 'in-progress-learning-required',
    evidenceInventoryHash: t002Hash('t001-evidence-inventory'),
    ...overrides,
  };
  return { ...body, eventHash: sha256(canonicalJson(body)) };
}

/** Authorize the same otherwise-valid autonomous attempt against the workspace lane history. @param {string} root */
function t001Authorize(root) {
  const runCommand = runtimeFunction('runCommand');
  return runCommand('authorize', {
    trigger: 'post-failure',
    state: autonomousState(),
    input: autonomousInspectInput(root),
    assessment: {
      ...transitionAssessment('retry-task'),
      evidenceHash: inspect(autonomousInspectInput(root)).evidenceHash,
    },
    mode: 'recovery',
  }).authorization;
}

test('T001 shared declaration: a declared audit-only lane record authorizes autonomously and is never rewritten', () => {
  withAutonomousWorkspace(noRegistryPlanBytes(SPEC_PATH), (root) => {
    // Arrange
    const tasksPath = path.join(root, TASKS_PATH);
    const auditBytes = t002HistoryTasksRecordBytes([`${t002V2EventLine(t001AuditOnlyEvent())}\n`]);

    // Act
    const withoutAudit = t001Authorize(root);
    fs.writeFileSync(tasksPath, auditBytes);
    const withAudit = t001Authorize(root);

    // Assert
    assert.equal(withoutAudit.authorized, true);
    assert.equal(withAudit.authorized, true);
    assert.equal(Object.hasOwn(withAudit, 'blocker'), false);
    // The read is reader-side only: the append-only record survives byte-identical.
    assert.deepEqual(fs.readFileSync(tasksPath), auditBytes);
  });
});

test('T001 shared declaration: a corrupt declared audit-only lane record still fails closed', () => {
  withAutonomousWorkspace(noRegistryPlanBytes(SPEC_PATH), (root) => {
    // Arrange
    const valid = t001AuditOnlyEvent();
    const corruptRecords = [
      ['tampered body', { ...valid, evidenceInventoryHash: t002Hash('t001-tampered-inventory') }],
      // Self-consistent bytes carrying a contradictory branch: an audit-only
      // record is validated exactly as strictly as a retention-relevant one.
      ['contradictory branch', t001AuditOnlyEvent({ branch: 'evidence-incomplete' })],
      ['foreign target', t001AuditOnlyEvent({ target: canonicalTarget(TARGET) })],
    ];

    // Act and Assert
    for (const [label, event] of corruptRecords) {
      fs.writeFileSync(
        path.join(root, TASKS_PATH),
        t002HistoryTasksRecordBytes([`${t002V2EventLine(/** @type {Record<string, unknown>} */ (event))}\n`]),
      );
      const refused = t001Authorize(root);
      assert.equal(refused.authorized, false, /** @type {string} */ (label));
      assert.equal(refused.reason, 'evidence-incomplete', /** @type {string} */ (label));
      assert.equal(refused.blocker.subject, 'occurrence-retention', /** @type {string} */ (label));
      assert.equal(classifyOutcomeReason(refused.reason), 'hard-stop', /** @type {string} */ (label));
    }
  });
});

